// ---- tabs.list ----

/**
 * Arguments of `tabs.list`.
 * Arguments/output for commands that take or return nothing: `{}`.
 */
export type TabsListArgs = Record<string, never>;

/** Result of `tabs.list`. */
export interface TabsListOutput {
  /**
   * Open tabs in tab-strip order; `groupId` / `lockedBy` / `lock` say which agent owns
   * a tab.
   */
  tabs: {
    /** Tab id, used as `tab` argument by other commands. */
    id: number;
    /** Page title. */
    title: string;
    /** Current URL. */
    url: string;
    /** True while the page is still loading. */
    loading: boolean;
    /**
     * Favicon URL; null until the page reports one.
     * @default null
     */
    favicon: string | null;
    /**
     * True when `nav.back` would do something.
     * @default false
     */
    canGoBack: boolean;
    /**
     * True when `nav.forward` would do something.
     * @default false
     */
    canGoForward: boolean;
    /**
     * True for the tab shown in its window (one per window).
     * @default false
     */
    active: boolean;
    /**
     * Tab group id. Always null for now (tab groups are not implemented yet).
     * @default null
     */
    groupId: string | null;
    /**
     * Agent holding the tab lock. Always null for now (agent locks come later).
     * @default null
     */
    lockedBy: string | null;
    /**
     * Profile (= workspace in the UI) the tab runs in. Absent for backends without
     * profiles.
     */
    profile?: string | null;
    /** In-memory profile (nothing written to disk). Absent = false. */
    incognito?: boolean;
    /**
     * Off-screen (windowless automation) tab: not shown in any window's tab strip.
     * Absent = false.
     */
    offscreen?: boolean;
    /** Browser window that shows the tab. Absent for off-screen tabs. */
    window?: number | null;
    /** Set while the tab is one half of a split view (`tabs.split`). */
    split?: {
      /** The half this tab is shown in. */
      side: "left" | "right";
      /** The tab in the other half. */
      other: number;
      /** Width of the left half as a fraction of the page area (0.15–0.85). */
      ratio: number;
    } | null;
    /** Page zoom in percent when it is not 100 (`page.zoom`, Ctrl+= / Ctrl+-). */
    zoom?: number | null;
    /** Agent lock of the tab; null when no agent owns it. */
    lock: {
      /** Agent whose group the tab is in. */
      owner: string;
      /**
       * Who controls an agent-owned tab right now.
       *
       * - `"active"`: The owner agent drives the tab; everyone else except humans is refused.
       * - `"paused"`: A human took over; agents are refused until the human gives it back (`tabs.lock`).
       * - `"handoff"`: The agent handed the tab to the human (`ai.handoff`) and waits for "Done" (`tabs.unlock`), which makes it `active` again.
       */
      state: "active" | "paused" | "handoff";
      /** `handoff`: what the agent asks the user to do. */
      reason: string | null;
      /** When the state last changed, ms since the Unix epoch. */
      sinceMs: number;
    } | null;
  }[];
  /** Tab groups: one per known agent (`agent:<id>`). */
  groups: {
    id: string;
    name: string;
    /** grey | blue | red | yellow | green | pink | purple | cyan | orange */
    color: string;
    /** Set for agent-owned groups. */
    agentId: string | null;
  }[];
  /** The tab the user is looking at, or null when no tab is open. */
  activeId: number | null;
}

